add('air-fryer-steak-fajitas','Steak fajita filling',Q,2,180,5,18,[[1,'each','medium sirloin steak','Cut across grain into thin strips'],[2,'each','capsicums','Sliced'],[1,'each','red onion','Sliced'],[15,'ml','olive oil'],[30,'ml','fajita seasoning']],['Toss the sliced capsicum and onion with oil and fajita seasoning. Reserve some seasoning for the steak.','Air fry the vegetables at 180°C for 10 minutes. Stir, add seasoned steak in an even layer and cook for a further 8 minutes.','Serve the filling hot. Tortillas, sour cream and rice are optional extras outside the nutrition estimate.'],internal=71,allergens=['wheat','gluten'],nutritionNote='Source estimate includes the steak and vegetable filling only; tortillas are excluded. A medium sirloin has no specified weight. Check seasoning allergens.')
add('air-fryer-chicken-fajitas','Chicken fajita filling',Q,2,180,5,18,[[2,'each','medium chicken breasts','Cut into even narrow strips'],[2,'each','capsicums','Sliced'],[1,'each','red onion','Sliced'],[15,'ml','olive oil'],[30,'ml','fajita seasoning']],['Coat the vegetables with oil and fajita seasoning; reserve a little of the seasoning for the chicken.','Cook the vegetables at 180°C for 6 minutes, then shake the basket. Add seasoned chicken in a single layer and cook another 12 minutes, turning once.','Serve when the chicken reaches 74°C. Tortillas and other serving extras are not included in the nutrition.'],internal=74,allergens=['wheat','gluten'],tags=['chicken breast'],nutritionNote='Publisher estimate for half the filling. Source uses two medium breasts without weights; tortillas and toppings excluded. Check spice-blend label.')
add('air-fryer-chicken-drumsticks','Roast chicken drumsticks',C,2,180,5,20,[[600,'g','chicken drumsticks','About four pieces; raw bone-in weight'],[7.5,'ml','olive oil'],[2,'tsp','mixed herbs','','dried']],['Rub drumsticks with oil and mixed herbs. Arrange in a single layer with gaps around the thick ends.','Air fry at 180°C for 17–20 minutes, turning halfway. Probe the meatiest area away from bone and continue until 74°C.'],portion='Half the batch, about two drumsticks or 300 g raw bone-in weight.',nutritionNote='Publisher estimate per two drumsticks from a 600 g bone-in pack. Bones are excluded from edible yield; actual meat and skin intake varies.')
add('lemon-rosemary-chicken-potatoes-in-the-air-fryer','Lemon roast chicken and potato wedges',Q,4,180,5,48,[[1,'each','medium whole chicken','Remove giblets and packaging'],[4,'each','medium potatoes','Cut into wedges'],[2,'each','lemons','One half for cavity; rest cut into wedges'],[4,'each','garlic cloves'],[30,'ml','olive oil','Divide between chicken and potatoes'],[15,'ml','balsamic vinegar'],[30,'ml','oregano','','dried'],[2,'tsp','parsley','','dried']],['Check the chicken fits with clear space above and around it. Put half a lemon and garlic in the cavity. Brush the skin with half the oil and season with half the oregano.','Place breast down and air fry at 180°C for 20 minutes. Toss potato wedges with remaining oil, vinegar and parsley.','Turn chicken breast upwards. Add remaining oregano, potatoes and lemon wedges around it without packing tightly. Cook a further 28 minutes, checking chicken and potatoes.','Verify 74°C in both the breast and inner thigh, and that the potatoes are tender. Rest the chicken for 10 minutes.'],wait=10,internal=74,safety=['A whole chicken may not fit your basket. Use the measured clearance in your appliance manual; do not force the lid or crowd the basket.'],nutritionNote='Publisher estimate is one quarter of an unspecified medium chicken plus potatoes. The source title mentions rosemary but its actual ingredients use oregano; this adaptation follows the ingredient list.')
add('air-fryer-steak-bites-and-potatoes','Sirloin bites and roast potatoes',Q,2,180,5,20,[[500,'g','sirloin steak','Cut into 2.5 cm cubes'],[1,'each','large white potato','Cut into 1.5 cm cubes'],[7.5,'ml','olive oil'],[1,'tsp','smoked paprika'],[1,'tsp','parsley','','dried']],['Toss potatoes with oil, paprika and parsley. Air fry at 180°C for 12 minutes, shaking once.','Add seasoned steak cubes, spread out with space between pieces, and cook 6–8 minutes more, turning halfway.','Check the steak temperature and potato tenderness. Continue in short intervals if either needs longer.'],internal=71,nutritionNote='Source estimate retained for half the 500 g steak batch plus potato. Source cook-time metadata says 6 minutes but method includes 12 minutes for potatoes; displayed time corrects this omission.')
add('air-fryer-meatball-potato-traybake','Cheesy beef meatballs and root vegetables',Q,2,180,10,26,[[.5,'each','yellow capsicum','Cut into strips'],[.5,'each','swede','Peeled and cut into narrow batons'],[1,'each','carrot','Peeled and cut into narrow batons'],[.5,'each','large potato','Cut into narrow batons'],[2,'tsp','olive oil'],[15,'ml','mixed herbs','','dried'],[500,'g','beef mince'],[.5,'each','white onion','Finely diced'],[30,'ml','Red Leicester cheese','Grated'],[2,'tsp','tomato paste'],[2,'tsp','oregano','','dried']],['Toss swede, carrot and potato with oil and mixed herbs. Air fry at 180°C for 13 minutes.','Mix beef, onion, cheese, tomato paste and oregano. Shape into similar 3 cm meatballs.','Shake the vegetables and add capsicum. Arrange the meatballs with space around them and cook for another 13 minutes, turning once. Check several meatballs at their centres.'],allergens=['milk'],internal=71,nutritionNote='Publisher estimate is for half the full recipe using its unspecified-fat beef mince. This is a substantial 875 kcal portion; values must not be read as lean-mince nutrition.')
add('air-fryer-tuna-steak','Tuna steaks with basil tomatoes',S,2,190,5,9,[[2,'each','tuna steaks','Similar size and thickness'],[15,'ml','olive oil'],[125,'g','cherry tomatoes','Halved'],[2,'tsp','basil','','dried'],[1,'tsp','thyme','','dried'],[1,'tsp','oregano','','dried']],['Toss tomatoes with oil and basil. Season tuna with thyme and oregano.','Place steaks apart in the basket and fit the tomatoes around them. Air fry at 190°C for 7 minutes.','Check the thickest part of each steak; add 2-minute intervals until 63°C. This version cooks the tuna through.'],allergens=['fish'],turn='Turn carefully halfway through if needed for even cooking.',nutritionNote='Publisher estimate per tuna steak plus half the tomatoes. The source does not specify steak weight; thicker or larger steaks alter timing and nutrients.')
add('air-fryer-chicken-burrito-bowl','Chicken, black bean and avocado bowls',Q,2,180,12,17,[[450,'g','chicken breast tenderloins'],[120,'g','mixed sliced capsicums','','frozen'],[150,'g','sweetcorn','','frozen'],[150,'g','black beans','Drained','canned'],[100,'g','reduced-fat cheddar','Grated'],[.5,'each','iceberg lettuce','Shredded'],[1,'each','cucumber','Sliced'],[7,'each','cherry tomatoes','Halved'],[1,'each','avocado','Sliced'],[30,'ml','salsa'],[30,'ml','fat-free Greek yoghurt'],[15,'ml','Mexican seasoning']],['Season chicken and air fry in one layer at 180°C for 10 minutes. Add frozen capsicum and cook another 4 minutes.','Put sweetcorn in a small approved ramekin. Add it to the basket and cook for 3 minutes more. Check chicken reaches 74°C and heat frozen vegetables according to their packet; extend cooking if necessary.','Divide lettuce, cucumber, tomatoes, avocado and drained beans between two bowls. Add sliced chicken, capsicum, corn and cheese. Spoon over salsa and yoghurt.'],internal=74,allergens=['milk','wheat','gluten'],oilFree=True,equipment=['Air-fryer-safe ramekin'],nutritionNote='Publisher estimate per one of two substantial bowls, including all cheese and avocado. The mixed seasoning may contain wheat; check the label.')
add('air-fryer-lamb-steaks','Mint and honey lamb steaks',M,4,180,5,12,[[4,'each','lamb steaks','About 2 cm thick'],[1,'tsp','chopped garlic','','frozen'],[2,'tsp','olive oil'],[2,'tsp','lemon juice'],[2,'tsp','honey'],[1,'tsp','thyme','','dried'],[30,'ml','mint','Finely chopped','fresh']],['Mix garlic, oil, lemon, honey, thyme and mint. Rub over the steaks, cover and refrigerate for 1 hour.','Arrange in a single layer. Air fry at 180°C for 10–12 minutes, turning halfway, until the thickest part reaches 71°C.','Rest for 3 minutes before serving.'],wait=63,internal=71,nutritionNote='Source estimate per lamb steak, with unspecified steak weight. The 1-hour refrigerated marinade and 3-minute rest are included in total time.')
add('air-fryer-turkey-legs','Herb-roasted turkey drumsticks',C,4,180,5,35,[[2,'each','turkey drumsticks','Must fit basket without touching heating element'],[15,'ml','mixed herbs','','dried'],[15,'ml','olive oil']],['Coat the drumsticks with oil and herbs. Place apart in the basket.','Air fry at 180°C for 20 minutes, turn and cook for another 10–15 minutes. Probe deeply beside the bone; large drumsticks may require substantially longer.','When both reach 74°C, rest for 5 minutes. Remove bones and divide the meat into four portions.'],wait=5,nutritionNote='Publisher estimate for one quarter of two unspecified-size turkey drumsticks. Do not infer edible weight from piece count; a large drumstick can change both nutrients and required time.')
add('air-fryer-boneless-turkey-breast','Balsamic roast turkey breast',C,4,160,5,40,[[1400,'g','boneless turkey breast'],[15,'ml','olive oil'],[15,'ml','balsamic vinegar'],[15,'ml','thyme','','dried'],[15,'ml','oregano','','dried'],[.25,'tsp','garlic salt']],['Rub the turkey with balsamic vinegar, oil, herbs and garlic salt. Check it fits with air circulation around it.','Air fry at 160°C for 15 minutes, turn and cook for another 15 minutes.','Using a clean board, slice thick portions and return them in one layer for 5–10 minutes or longer until every portion reaches 74°C. Sanitise the board and knife after contact with undercooked meat.','Rest for 5 minutes and divide into four equal portions.'],wait=5,nutritionNote='Publisher estimate is for a quarter of 1.4 kg raw boneless turkey, a large 350 g raw portion. The displayed protein is not for a small slice.')
add('air-fryer-balsamic-chicken-vegetables','Balsamic chicken with courgette and tomatoes',Q,4,180,5,17,[[1,'each','large chicken breast','Cut into 2.5 cm chunks'],[10,'each','cherry tomatoes','Halved'],[1,'each','small zucchini','Cut into thick quarter rounds'],[1,'each','capsicum','Cut into chunks'],[15,'ml','balsamic vinegar'],[15,'ml','honey'],[15,'ml','olive oil'],[1,'tsp','oregano','','dried'],[1,'tsp','basil','','dried'],[1,'tsp','garlic paste']],['Mix vinegar, honey, oil, herbs and garlic. Toss with chicken and the prepared vegetables.','Spread in a shallow, single layer. Air fry at 180°C for 12 minutes, stirring halfway.','Stir again and increase to 200°C for 5 minutes. Check every large chicken piece reaches 74°C.'],internal=74,nutritionNote='Source estimate divides a single large chicken breast among four light portions. It is only 13 g protein per serving; no grain or side is included.')
add('air-fryer-cajun-shrimp','Cajun prawns with lemon',S,2,180,2,8,[[30,'each','peeled prawns','Frozen; similar medium size','frozen'],[.5,'tsp','olive oil'],[15,'ml','Cajun seasoning'],[1,'tsp','garlic paste'],[1,'each','lemon','Juice only']],['Toss the frozen prawns with oil, Cajun seasoning and garlic. Spread evenly without a thick pile.','Air fry at 180°C for 6–8 minutes, shaking halfway. Continue until the centres reach 63°C and the flesh is opaque.','Finish with lemon juice and serve immediately.'],allergens=['crustacean','wheat','gluten'],nutritionNote='Source estimate is for 15 unspecified-size frozen prawns. Size and glaze vary; check package weight and Cajun seasoning allergens.')
add('air-fryer-lamb-kofta-kebabs','Lamb kofta fingers',M,4,180,5,16,[[500,'g','lamb mince'],[1,'tsp','ground coriander'],[1,'tsp','mixed spice'],[1,'tsp','chilli flakes'],[1,'tsp','turmeric'],[1,'tsp','cumin'],[1,'tsp','mixed herbs','','dried'],[.5,'tsp','tandoori seasoning']],['Knead lamb with all spices just until the mixture binds. Shape into eight equal fingers, approximately 2 cm thick.','Lay directly in the basket with gaps. Air fry at 180°C for 8 minutes, turn and cook another 8 minutes. Check the centre of several kofta reaches 71°C.'],internal=71,oilFree=True,allergens=['wheat','gluten'],portion='Two kofta; one quarter of the 500 g raw lamb batch.',nutritionNote='Publisher estimate per 125 g raw lamb plus spices. Fat content follows the source mince and may differ substantially for lean mince. Flatbread and sauces excluded.')
add('air-fryer-shrimp-fajitas','Prawn and capsicum fajita filling',Q,1,180,3,10,[[250,'g','peeled cooked prawns','','frozen'],[300,'g','capsicums','Sliced'],[1,'each','white onion','Sliced'],[30,'ml','fajita seasoning']],['Combine frozen cooked prawns, sliced vegetables and seasoning. Spread in a shallow layer in the basket.','Air fry at 180°C for 8–10 minutes, shaking midway. Continue until prawns are piping hot throughout and the vegetables are tender.','Serve as filling or in a bowl. Tortillas and other extras are outside the estimate.'],internal=75,allergens=['crustacean','wheat','gluten'],oilFree=True,nutritionNote='Publisher estimate is the whole 250 g prawn batch as one serving. Prawns are precooked frozen, not raw. Tortillas excluded.')
add('air-fryer-pork-loin','Oil-free herb pork loin',M,4,180,3,65,[[1500,'g','pork loin'],[15,'ml','pork seasoning'],[15,'ml','bouquet garni herb mix','','dried']],['Check the intact loin fits with clearance around it. Rub the seasonings over all surfaces.','Air fry at 180°C for 35 minutes. Turn carefully and cook for another 30 minutes, checking the centre with a thermometer.','Continue as needed to reach 71°C, then rest for 10 minutes before carving into four equal portions.'],wait=10,internal=71,oilFree=True,allergens=['wheat','gluten'],nutritionNote='Publisher estimate per quarter of a 1.5 kg loin: approximately 375 g raw meat, a large portion. No sides included. Check seasoning ingredients.')
add('air-fryer-tandoori-chicken-kebabs','Yoghurt-marinated tandoori chicken',C,4,190,10,30,[[500,'g','chicken breast','Cut into 3 cm chunks'],[45,'ml','Greek yoghurt'],[2,'tsp','garlic paste'],[2,'tsp','ginger paste'],[2,'tsp','turmeric'],[1,'tsp','garam masala'],[1,'tsp','ground coriander'],[2,'tsp','paprika'],[.5,'tsp','cayenne pepper']],['Mix yoghurt, garlic, ginger and spices. Coat the chicken, cover and refrigerate for 8 hours.','Thread onto manufacturer-approved skewers that fit the basket, leaving small gaps; alternatively spread pieces directly in one layer. Discard used marinade.','Air fry at 190°C for up to 30 minutes, turning at 15 minutes. Begin checking at 20 minutes and remove once all pieces reach 74°C to avoid drying.'],wait=480,allergens=['milk'],oilFree=True,nutritionNote='Publisher estimate for a quarter of the 500 g chicken batch. The long refrigerated marinade is included in total time. No naan or rice included.')
add('nandos-peri-peri-chicken-bowl-in-the-air-fryer','Peri-peri chicken and brown rice bowls',Q,4,180,5,12,[[500,'g','brown rice','Cooked and chilled safely','cooked'],[400,'g','chicken breast','Cut into 2.5 cm pieces'],[125,'g','sweetcorn','','frozen'],[30,'ml','peri-peri dry rub']],['Coat chicken with peri-peri rub. Place in a shallow approved air-fryer pan with frozen sweetcorn.','Air fry at 180°C for 10–12 minutes, stirring midway, until chicken reaches 74°C and corn is steaming hot.','Heat the cooked rice thoroughly according to its packet or safe leftover guidance. Divide rice, chicken and corn between four bowls.'],internal=74,oilFree=True,allergens=['wheat','gluten','sulphites'],equipment=['Air-fryer-safe shallow pan'],nutritionNote='Publisher estimate includes 500 g already cooked brown rice across four portions. Do not substitute 500 g dry rice. Dry-rub brands differ; check allergens.')
add('air-fryer-chicken-taquitos','Chicken and cheese taquitos',Q,8,180,5,18,[[1,'each','medium chicken breast','Flatten to an even 2 cm thickness'],[75,'g','cheddar','Grated'],[45,'ml','cream cheese'],[60,'ml','salsa'],[8,'each','small corn tortillas'],[2,'tsp','Mexican seasoning']],['Season chicken with half the Mexican seasoning. Air fry at 180°C for 8–10 minutes, turning once, and continue until 74°C. Shred using clean forks.','Mix the shredded chicken with cheddar, cream cheese, salsa and remaining seasoning. Divide between the tortillas and roll tightly.','Place seam down in a single layer and air fry for 8 minutes until crisp and hot through the centre.'],internal=75,oilFree=True,allergens=['milk','wheat','gluten'],portion='One taquito. Two or more may be needed for a meal; log the number actually eaten.',nutritionNote='Publisher estimate per one of eight taquitos. Optional egg wash is omitted. Confirm corn tortilla and spice blend labels for wheat cross-ingredients.')
add('air-fryer-shrimp-scampi','Garlic butter prawns with white wine',S,1,180,5,10,[[30,'each','peeled prawns','','frozen'],[40,'g','butter','Cubed'],[6,'each','garlic cloves','Thinly sliced'],[1,'each','small lemon','Juice only'],[75,'ml','white wine'],[15,'ml','parsley','Chopped','fresh'],[1,'tsp','oregano','','dried']],['Put butter, garlic, lemon juice, wine and herbs in a shallow approved air-fryer pan. Stir, then distribute the prawns through the mixture.','Air fry at 180°C for 8–10 minutes, stirring halfway. Check the largest prawns reach 63°C and are opaque.','Serve with the cooking juices. Bread or rice is an additional ingredient and is not included in the nutrition.'],allergens=['crustacean','milk','sulphites'],turn='Stir halfway through.',equipment=['Shallow air-fryer-safe pan'],nutritionNote='Publisher estimate covers the entire batch as one serving, including all 40 g butter and the wine. Prawn size is unspecified; alcohol is not guaranteed to cook off.')
